// RSS feeds: Yahoo Finance + Google News searches. Add/remove lines freely.
const gn = (q, c = 'US') =>
  `https://news.google.com/rss/search?q=${encodeURIComponent(q)}%20when:1d&hl=en-${c}&gl=${c}&ceid=${c}:en`;
const feeds = [
  // ---- Yahoo Finance ----
  'https://finance.yahoo.com/news/rssindex',
  'https://feeds.finance.yahoo.com/rss/2.0/headline?s=%5EGSPC,%5EDJI,%5EIXIC,%5ENSEI,%5EBSESN&region=US&lang=en-US',
  // ---- Google News: international (Trump / exchanges / big money) ----
  gn('Trump stock market'),
  gn('Wall Street stock exchange stocks'),
  gn('institutional investors billion inflows markets'),
  gn('FTSE London Nikkei Hang Seng markets'),
  // ---- Google News: India ----
  gn('Nifty Sensex', 'IN'),
  gn('FII DII flows India stock market', 'IN'),
];
return feeds.map(url => ({ json: { url } }));

// ===================== settings you can edit =====================
const INTL_COUNT  = 5;    // international items: Trump / stock exchanges / big money flows
const OTHER_COUNT = 7;    // other market items (India first, then general)  -> 12 per run, never below MIN_TOTAL if available
const MIN_TOTAL   = 10;
const WINDOW_HOURS = Number($env.NEWS_LOOKBACK_HOURS || 6);   // "new" = published within this window
const SUMMARY_LEN = 220;
const THEMES = {
  TRUMP:    { label: '🇺🇸 Trump & Policy',   re: /trump|white house|tariffs?|truth social|executive order|bessent|powell|fed chair/i },
  EXCHANGE: { label: '🏛 Stock Exchanges',   re: /stock exchange|nyse|nasdaq|s&p 500|dow jones|dow\b|wall street|ftse|nikkei|hang seng|\bdax\b|cac 40|kospi|stoxx|shanghai|futures|\bipo\b|stocks? (rise|fall|slip|surge|tumble|rally|jump|drop)/i },
  MONEY:    { label: '💰 Big Money Flows',   re: /billion|trillion|inflows?|outflows?|etf flows?|institutional|hedge fund|sovereign wealth|buyback|record investment|block deal|capital flows?|\bfii\b|\bfpi\b|\bdii\b|whales?|mega.?deal|acquisition|takeover|merger|stake/i },
};
const INDIA_RE = /nifty|sensex|\bnse\b|\bbse\b|india|rupee|sebi|dalal|mumbai|\bfii\b|\bdii\b/i;
// =================================================================

const safe = n => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
const strip = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim();
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = s => esc(s).replace(/"/g, '&quot;');
const isUrl = u => typeof u === 'string' && /^https?:\/\//i.test(u);
const host = u => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };

const raw = { yahoo: 0, google: 0, finnhub: 0, other: 0 };
const items = [];

// ---- RSS (Yahoo + Google News) ----
for (const j of safe('Read RSS')) {
  if (!j.title || !j.link) continue;
  const h = host(j.link);
  let title = strip(j.title), source = '', origin = 'other';
  if (h.includes('news.google.com')) {
    origin = 'google';
    const k = title.lastIndexOf(' - ');
    if (k > 0) { source = title.slice(k + 3); title = title.slice(0, k); }
    source = source || 'Google News';
  } else if (h.includes('yahoo.com')) { origin = 'yahoo'; source = 'Yahoo Finance'; }
  else source = host(j.link);
  raw[origin]++;
  let summary = strip(j.contentSnippet || j.content || j.summary || '');
  if (!summary || summary.toLowerCase().startsWith(title.toLowerCase().slice(0, 30))) summary = '';
  const imgFromHtml = (String(j.content || '').match(/<img[^>]+src=["']([^"']+)["']/i) || [])[1];
  const image = [j.enclosure && j.enclosure.url, j['media:content'] && j['media:content'].$ && j['media:content'].$.url,
                 j.mediaContent && j.mediaContent.url, imgFromHtml].find(isUrl) || '';
  const t = Date.parse(j.isoDate || j.pubDate || '') || 0;
  items.push({ title, link: j.link, source, summary, image, t, origin });
}
// ---- Finnhub market news (general + merger) ----
for (const n of ['Finnhub General', 'Finnhub Merger']) {
  for (const j of safe(n)) {
    if (!j.headline || !j.url) continue;
    raw.finnhub++;
    items.push({ title: strip(j.headline), link: j.url, source: j.source || 'Finnhub', summary: strip(j.summary || ''),
                 image: isUrl(j.image) ? j.image : '', t: (j.datetime || 0) * 1000, origin: 'finnhub' });
  }
}

const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
const counts = `Google ${raw.google} · Yahoo ${raw.yahoo} · Finnhub ${raw.finnhub}`;
if (!items.length) {
  return [{ json: { text: `⚠️ <b>Market Update</b> — ${now} IST\nNo stories could be fetched (${counts}).\nCheck the network and FINNHUB_API_KEY.`, lpo: { is_disabled: true } } }];
}

// ---- de-duplicate, tag, rank ----
const sd = $getWorkflowStaticData('global');
const sentBefore = new Set(sd.sent || []);
const seenKey = new Set(); const pool = [];
for (const it of items) {
  const k = it.title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 60);
  if (!k || seenKey.has(k) || seenKey.has(it.link)) continue;
  seenKey.add(k); seenKey.add(it.link);
  const txt = it.title + ' ' + it.summary;
  it.india = INDIA_RE.test(txt);
  it.themes = Object.keys(THEMES).filter(x => THEMES[x].re.test(txt));
  it.fresh = it.t === 0 || it.t >= Date.now() - WINDOW_HOURS * 3600e3;
  it.unseen = !sentBefore.has(it.link);
  it.score = it.t + (it.image ? 45 * 60e3 : 0);
  pool.push(it);
}
const rank = (a, b) => (b.unseen - a.unseen) || (b.fresh - a.fresh) || (b.score - a.score);
pool.sort(rank);

const picked = []; const used = new Set();
const take = (it, theme) => { if (used.has(it) ) return false; used.add(it); it.theme = theme; picked.push(it); return true; };

// 1) international: round-robin Trump -> Exchange -> Money
const intlPool = pool.filter(i => !i.india);
const lanes = Object.keys(THEMES).map(k => intlPool.filter(i => i.themes.includes(k)));
let n = 0, guard = 0;
while (n < INTL_COUNT && guard++ < 100) {
  let progressed = false;
  for (let li = 0; li < lanes.length && n < INTL_COUNT; li++) {
    const next = lanes[li].find(i => !used.has(i));
    if (next && take(next, Object.keys(THEMES)[li])) { n++; progressed = true; }
  }
  if (!progressed) break;
}
for (const it of intlPool) { if (n >= INTL_COUNT) break; if (take(it, it.themes[0] || null)) n++; }   // top up with other international stories

// 2) other: India first (up to 4), then everything else
let m = 0;
for (const it of pool.filter(i => i.india)) { if (m >= Math.min(4, OTHER_COUNT)) break; if (take(it, null)) m++; }
for (const it of pool) { if (m >= OTHER_COUNT) break; if (take(it, it.themes[0] && !it.india ? it.themes[0] : null)) m++; }
// 3) guarantee the minimum
for (const it of pool) { if (picked.length >= MIN_TOTAL) break; take(it, null); }

sd.sent = [...sentBefore, ...picked.map(i => i.link)].slice(-300);

const ago = t => { if (!t) return ''; const mins = Math.max(1, Math.round((Date.now() - t) / 60000));
  return mins < 60 ? `${mins}m ago` : mins < 1440 ? `${Math.round(mins / 60)}h ago` : `${Math.round(mins / 1440)}d ago`; };

const intlShown = picked.filter(i => !i.india && i.themes.length).length;
const out = [{ json: {
  text: `🌍 <b>Market Update</b> — ${now} IST\n${picked.length} stories · ${intlShown} international (Trump / exchanges / big money)\nSources: ${counts}`,
  lpo: { is_disabled: true } } }];
for (const it of picked) {
  const label = it.theme ? THEMES[it.theme].label : (it.india ? '🇮🇳 India Markets' : '📰 Markets');
  const summary = it.summary ? '\n' + esc(it.summary.length > SUMMARY_LEN ? it.summary.slice(0, SUMMARY_LEN).trim() + '…' : it.summary) : '';
  const text = `${label}\n<b>${esc(it.title)}</b>${summary}\n🔗 <a href="${escAttr(it.link)}">${esc(it.source)}</a>${it.t ? ' · ' + ago(it.t) : ''}`;
  // image (if any) shows above the text; otherwise Telegram previews the article page
  out.push({ json: { text, lpo: { url: it.image || it.link, prefer_large_media: true, show_above_text: true } } });
}
return out;
